            out.rows = tool.drawnLast ? out.rows.filter(function (r) { return !drawnRow(r); }).concat(out.rows.filter(drawnRow)) :
                out.rows.filter(drawnRow).concat(out.rows.filter(function (r) { return !drawnRow(r); }));
