        if (o.point) body += '<circle class="calc-sv-dot" cx="' + fix(px(o.point[0])) + '" cy="' + fix(py(o.point[1])) + '" r="3.5"/>';
        if (o.names) body += svgText(R, B + 11, o.names[0], 'end') + svgText(L + 4, T + 2, o.names[1]);
