        rows = find ? [['R<sub>x</sub>, Ω', rx]] : [[isFinite(V) ? 'V<sub>out</sub>' : 'V<sub>out</sub> ÷ V', b.out], ['Balanced at R<sub>x</sub>, Ω', CalcPhysics.bridgeRx(v.R1, v.R2, v.R3)]];
        rows.push(['R<sub>out</sub>, Ω', b.r]);
