        for (i = 0; i <= 160; i++) stops += '<stop offset="' + (i / 160).toFixed(3) + '" stop-color="' + col + '" stop-opacity="' + Math.min(1, Math.sqrt(Math.max(0, f(i / 160)))).toFixed(2) + '"/>';
