            if (cnt.bad.length) return bioWarn(none, escaped(cnt.bad[0]) + ' is not a count.', ['c']);
            if (!cnt.values.length || cnt.values.some(function (x) { return x < 0 || x % 1; })) return bioWarn(none, 'Whole counts of 0 or more.', ['c']);
