            if (raw.n && !(n.n >= 1 && n.n <= N && n.n % 1 === 0)) return bioWarn(none, 'A sample from 1 to ' + N + ', whole.', ['n']);
            S = cnt.values.filter(function (x) { return x > 0; }).length;
