        rows = [{ l: { p: 'P, ' + ['atm', 'kPa', 'mmHg', 'bar'][+raw.pu || 0], v: 'V, L', n: 'n, mol', t: 'T, ' + (c ? '°C' : 'K') }[e.k], v: v }];
        if (e.k === 't') rows.push(c ? { l: 'T, K', v: v + c } : { l: 'T, °C', v: v - 273.15 });
